"""Run two complete offline builds and prove identical generated bytes.

Peer comparison and final seal follow the two builds, separately. No network,
Git, peer edits, external path writes, or source mutation.
"""
import hashlib,json,os,subprocess,sys
from pathlib import Path
H=Path(__file__).resolve().parent
SCRIPTS=['build_turnout.py','extract_legacy.py','extract_legacy_json.py','write_report.py']
GENERATED=['build-summary.json','candidate-universe.json','controls.json','registration-reconciliation.json','priority-set.json','sensitivity.json','legacy-observations.json','legacy-reconciliation.json','legacy-native-rosters.json','legacy-candidate-identities.json','legacy-json-observations.json','legacy-json-reconciliation.json','legacy-json-native-rosters.json','legacy-volume-sensitivity.json','legacy-state-election-reconciliation.json','../county-turnout.csv','../../turnout.md']
def hashes():
    paths=[H/p for p in GENERATED]+sorted((H/'extracts').glob('*'))
    return {os.path.relpath(p,H):{'bytes':p.stat().st_size,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()}for p in paths if p.is_file()}
results=[]
for i in [1,2]:
    for name in SCRIPTS:
        subprocess.run([sys.executable,str(H/name)],env={**os.environ,'PYTHONDONTWRITEBYTECODE':'1'},check=True,stdout=subprocess.DEVNULL)
    results.append(hashes());print('complete offline build',i,flush=True)
assert results[0]==results[1],'non-deterministic generated output'
(H/'reproduction.json').write_text(json.dumps({'status':'pass_two_complete_offline_builds_byte_identical','scripts':SCRIPTS,'generated_assets':results[1]},indent=2)+'\n')
print('byte-identical generated assets',len(results[1]),flush=True)
